      images: [{ url: "https://i.ytimg.com/vi/JLf9q36UsBk/maxres2.jpg", credit: "Big Machine Records / Taylor Swift via YouTube", caption: "Frost-covered mid-blizzard — a still from Joseph Kahn's official 'Out of the Woods' video, premiered on New Year's Eve 2015.", kind: "primary", focalPoint: "48% 42%" }],
