      sources: [{ name: "Love Story (Taylor Swift song)", url: "https://en.wikipedia.org/wiki/Love_Story_(Taylor_Swift_song)", reliability: 2, type: "wiki" }, { name: "'Love Story': The Story Behind The Classic Taylor Swift Song", url: "https://www.wideopencountry.com/love-story-taylor-swift/", reliability: 3, type: "reputable_press" }],
