      images: [{ url: "https://i.ytimg.com/vi/p1cEvNn88jM/hqdefault.jpg", credit: "Republic Records / YouTube (official audio still)", caption: "Artwork from the official 'I Forgot That You Existed' audio upload on Taylor Swift's YouTube channel.", kind: "archival", focalPoint: "50% 60%" }],
      sources: [{ name: "Rolling Stone", url: "https://www.rollingstone.com/music/music-features/taylor-swift-rolling-stone-interview-880794/" }, { name: "Songfacts", url: "https://www.songfacts.com/facts/taylor-swift/i-forgot-that-you-existed" }],
