      images: [{ url: "https://i.ytimg.com/vi/Kwf7P2GNAVw/hqdefault.jpg", credit: "Republic Records / YouTube (official audio still)", caption: "Artwork from the official 'Miss Americana & The Heartbreak Prince' audio upload on Taylor Swift's YouTube channel.", kind: "archival", focalPoint: "50% 45%" }],
