      images: [{ url: "https://tayswiftstyle.wordpress.com/wp-content/uploads/2018/05/tumblr_p8jr4cwjzw1r4fk4fo1_1280.jpg?w=1100", credit: "Taylor Swift Style", kind: "primary" }],
      sources: [{ name: "Taylor Swift Style", url: "https://tayswiftstyle.wordpress.com/2018/05/11/reputation-tour-call-it-what-you-want-this/" }, { name: "Billboard", url: "https://www.billboard.com/articles/columns/pop/8455193/taylor-swift-reputation-tour-best-moments" }],
      products: [{ brand: "Elizabeth K", item: "GL3159 Sequin Long Sleeve Slit Gown", retailer: "formaldressshops.com", url: "https://formaldressshops.com/products/sequin-fitted-long-sleeve-slit-gown-by-elizabeth-k-gl3159", price: "$151.00", isAlternative: true, altNote: "Jessica Jones's custom closer gown was never sold at retail -- this is a current black sequin long-sleeve slit gown in the same fitted, floor-length spirit (no boots).", imageUrl: "https://cdn.shopify.com/s/files/1/0022/0132/1547/files/sequin-fitted-long-sleeve-slit-gown-by-elizabeth-k-gl3159-s-black-2x-large-3x-large-4x-large-black-champagne-formal-dresses-formaldressshops-464.jpg?v=1759460142" }],
