      images: [{ url: "https://upload.wikimedia.org/wikipedia/en/8/8f/Taylor_Swift_-_Speak_Now_cover.png", credit: "Big Machine Records (album cover art)", kind: "primary", focalPoint: "62% 18%" }, { url: "https://upload.wikimedia.org/wikipedia/commons/8/82/Taylor_Swift_Speak_Now_Tour_%286820796178%29.jpg", credit: "Eva Rinaldi, CC BY-SA 2.0, via Wikimedia Commons", caption: "Taylor Swift performing on the Speak Now World Tour, the tour supporting the album nominated at the 54th Grammy Awards.", kind: "reference" }],
      sources: [{ name: "Wikipedia", url: "https://en.wikipedia.org/wiki/Speak_Now" }, { name: "The Hollywood Reporter", url: "https://www.hollywoodreporter.com/music/music-news/grammy-awards-2012-winners-whitney-houston-death-adele-289778/" }],
