      images: [{ url: "https://wwd.com/wp-content/uploads/2011/10/taylor01.jpg", credit: "Via WWD", caption: "At her Wonderstruck fragrance launch at Macy's Herald Square, October 13, 2011 in New York City.", kind: "primary" }],
