      sources: [{ name: "Jason Kelce Reveals How His Life Has Changed Since Travis Kelce Started Dating Taylor Swift", url: "https://people.com/jason-kelce-reveals-how-his-life-has-changed-since-travis-kelce-taylor-swift-started-dating-12024707", reliability: 4, type: "reputable_press" }, { name: "Jason Kelce Gets Candid About How Life Has Changed Since Taylor Swift Joined the Family", url: "https://www.harpersbazaar.com/celebrity/latest/a73247382/jason-kelce-talks-impact-of-travis-taylor-swift-relationship-fame/", reliability: 3, type: "reputable_press" }, { name: "'A Whole Other Demographic' — Jason Kelce Details How Taylor Swift Elevated His Family's Fame", url: "https://www.profootballnetwork.com/jason-kelce-taylor-swift-family-fame-stratosphere/", reliability: 3, type: "reputable_press" }, { name: "Taylor Swift's star power sends Travis Kelce's jersey sales soaring", url: "https://www.kcur.org/sports/2023-09-28/taylor-swifts-travis-kelce-kansas-city-chiefs-jersey", reliability: 4, type: "reputable_press" }, { name: "Taylor Swift-Travis Kelce Podcast Delivers a Massive 15 Million Views, Stream Crashes", url: "https://www.hollywoodreporter.com/music/music-news/taylor-swift-travis-kelce-podcast-ratings-1236344673/", reliability: 4, type: "reputable_press" }, { name: "Kelce brothers reach $100 million-plus deal with Amazon for 'New Heights'", url: "https://awfulannouncing.com/podcasts/kelce-brothers-new-heights-amazon-deal.html", reliability: 3, type: "reputable_press" }, { name: "How Taylor Swift changed the NFL — and how the NFL changed Taylor Swift", url: "https://www.livenowfox.com/news/taylor-swift-nfl-impact-travis-kelce", reliability: 3, type: "reputable_press" }],
