      products: [{ brand: "Markarian", item: "Laila Floral Beaded Organza Strapless Gown", retailer: "markarian-nyc.com", url: "https://markarian-nyc.com/products/laila-white-floral-beaded-organza-strapless-gown-with-pink-and-yellow-applique-flowers", price: "$7,895.00", inStock: false, isAlternative: true, altNote: "The pink floral-brocade \"Laila\" she wore (~$4,115) is past-season, off the brand site. This is the same Markarian \"Laila\" style in white beaded organza, what it lists now — different color, sold out.", imageUrl: "https://cdn.shopify.com/s/files/1/0024/7195/2443/files/MS2620AD1029_OFW_1.jpg?v=1757606125" }],
